const root = $input.first().json ?? {};
const parent = $('Preparar contexto inbound').first().json ?? {};
const inbound = parent.inbound ?? {};
let catalog = { services: [], professionals: [] };
let defaults = {};
try {
  const ctx = $('Montar contexto agente').first().json ?? {};
  catalog = ctx.catalog ?? catalog;
  defaults = ctx.defaults ?? {};
} catch (_) {
  /* legado */
}

const UUID_RE =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const okUuid = (v) => typeof v === 'string' && UUID_RE.test(v.trim());

const sessionText = String(inbound.session_text ?? inbound.message ?? '').trim();

function parseAgentPayload(raw) {
  if (raw == null) return {};
  let v = raw;
  if (typeof v === 'string') {
    const s = v.trim().replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/\s*```$/i, '');
    try {
      v = JSON.parse(s);
    } catch (_) {
      return {};
    }
  }
  if (v && typeof v === 'object' && typeof v.output === 'string') {
    return parseAgentPayload(v.output);
  }
  return v && typeof v === 'object' ? v : {};
}

function resolveFromCatalog(value, list, nameKeys = ['name', 'title']) {
  if (okUuid(value)) return value.trim();
  const q = String(value ?? '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');
  if (!q) return null;
  for (const item of list) {
    const id = item.id;
    if (!okUuid(id)) continue;
    for (const k of nameKeys) {
      const n = String(item[k] ?? '')
        .toLowerCase()
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '');
      if (!n) continue;
      if (n.includes(q) || q.includes(n)) return id;
    }
  }
  return null;
}

function todayIsoDate() {
  return new Date().toISOString().slice(0, 10);
}

function tomorrowIsoDate() {
  const d = new Date();
  d.setUTCDate(d.getUTCDate() + 1);
  return d.toISOString().slice(0, 10);
}

function isIsoDate(value) {
  return /^\d{4}-\d{2}-\d{2}$/.test(String(value ?? ''));
}

/** "Amanhã" no histórico vence data da IA; rejeita datas passadas. */
function resolveAppointmentDate(rawDate, sessionText) {
  if (/amanha|amanhã/i.test(sessionText)) {
    return tomorrowIsoDate();
  }
  const candidate = rawDate ?? null;
  if (!isIsoDate(candidate)) return null;
  if (candidate < todayIsoDate()) return null;
  return candidate;
}

function parseTimeHint(text) {
  const m = String(text).match(/\b(\d{1,2})\s*[:h]\s*(\d{2})\b/i);
  if (!m) return null;
  const h = Math.min(23, parseInt(m[1], 10));
  const min = Math.min(59, parseInt(m[2], 10));
  return `${String(h).padStart(2, '0')}:${String(min).padStart(2, '0')}`;
}

const schedulingCue =
  /agendar|hor[aá]rio|marcar|corte|barba|amanh[aã]|\d{1,2}\s*[:h]\s*\d{2}/i.test(sessionText);

const out = parseAgentPayload(root.output ?? root.json ?? root);

const defaultCustomer = String(
  defaults.customer_id ?? $env.QA_DEFAULT_CUSTOMER_ID ?? '00000000-0000-4000-8000-000000004031',
).trim();

const customer_id =
  (okUuid(out.customer_id) ? out.customer_id.trim() : null) ??
  inbound.customer_id ??
  parent.enrichment?.customer_id ??
  parent.core_response?.customerId ??
  defaultCustomer;

let professional_id =
  out.professional_id ??
  out.professional ??
  resolveFromCatalog(out.professional_name, catalog.professionals ?? []);
if (!okUuid(professional_id) && schedulingCue && okUuid(defaults.professional_id)) {
  professional_id = defaults.professional_id;
}

let service_id =
  out.service_id ?? out.service ?? resolveFromCatalog(out.service_name, catalog.services ?? []);
if (!okUuid(service_id) && schedulingCue && okUuid(defaults.service_id)) {
  service_id = defaults.service_id;
}

const appointment_date = resolveAppointmentDate(
  out.appointment_date ?? out.date ?? null,
  sessionText,
);

let appointment_time = out.appointment_time ?? out.time ?? parseTimeHint(sessionText);

let intent = String(out.intent ?? '').trim();
if (!intent) {
  if (/^(oi|ol[aá]|bom dia|boa tarde|boa noite)\b/i.test(String(inbound.message ?? '')) && !schedulingCue) {
    intent = 'informacao_empresa';
  } else if (schedulingCue && okUuid(service_id) && okUuid(professional_id)) {
    intent = /agendar|marcar/i.test(sessionText) ? 'criar_agendamento' : 'consultar_horarios';
  } else {
    intent = 'consultar_horarios';
  }
}

let response_text = String(
  out.response_text ?? 'Recebemos sua mensagem. Em breve retornamos o contato.',
);
if (/autentica|authorization|unauthorized|401|403/i.test(response_text)) {
  response_text =
    'Recebemos sua mensagem. Para agendar, informe o servico (ex.: corte masculino), dia e horario preferido.';
}

const appointment_payload =
  out.appointment_payload && typeof out.appointment_payload === 'object'
    ? out.appointment_payload
    : {};

return [
  {
    json: {
      intent,
      professional_id: okUuid(professional_id) ? professional_id : null,
      service_id: okUuid(service_id) ? service_id : null,
      appointment_date: isIsoDate(appointment_date) ? appointment_date : null,
      appointment_time,
      customer_id,
      response_text,
      appointment_payload,
      inbound,
      session_text: sessionText,
    },
  },
];

/** Preserva payload WF01 + contexto multi-mensagem da sessão WhatsApp. */
const t = $input.first().json ?? {};
const enrichment = t.enrichment ?? {};
const normalized = t.normalized ?? {};
const core = t.core_response ?? {};
const conv = enrichment.conversation_context ?? t.conversation_context ?? {};

const sessionText = String(
  conv.session_text ?? conv.sessionText ?? normalized.text ?? '',
).trim();
const lastMessage = String(normalized.text ?? '').trim();

return [
  {
    json: {
      ...t,
      enrichment,
      normalized,
      core_response: core,
      conversation_context: conv,
      inbound: {
        phone: normalized.phone ?? null,
        message: lastMessage,
        session_text: sessionText || lastMessage,
        recent_messages: Array.isArray(conv.recent_messages) ? conv.recent_messages : [],
        customer_id: enrichment.customer_id ?? core.customerId ?? null,
        tenant_id: enrichment.tenant_id ?? core.tenantId ?? null,
        message_id: enrichment.message_id ?? core.messageId ?? null,
      },
    },
  },
];

/** Monta contexto limpo para o agente (sem vazar erros HTTP 401/403 ao cliente). */
const prep = $('Preparar contexto inbound').first().json ?? {};
const inbound = prep.inbound ?? {};

function unwrapList(payload) {
  if (!payload || typeof payload !== 'object') return [];
  if (Array.isArray(payload)) return payload;
  if (Array.isArray(payload.data)) return payload.data;
  if (Array.isArray(payload.items)) return payload.items;
  return [];
}

function isHttpErrorShape(o) {
  if (!o || typeof o !== 'object') return false;
  const msg = String(o.message ?? o.error ?? '').toLowerCase();
  const status = o.statusCode ?? o.status;
  return (
    status === 401 ||
    status === 403 ||
    msg.includes('unauthorized') ||
    msg.includes('authorization failed') ||
    msg.includes('forbidden')
  );
}

function safeApiSlice(nodeName) {
  try {
    const row = $(nodeName).first().json;
    if (!row || isHttpErrorShape(row)) return { ok: false, data: [] };
    return { ok: true, data: unwrapList(row) };
  } catch (_) {
    return { ok: false, data: [] };
  }
}

const services = safeApiSlice('Catalogo servicos Core API');
const professionals = safeApiSlice('Catalogo profissionais Core API');
const appointments = safeApiSlice('Contexto agenda Core API');

const catalog = {
  services: services.data.map((s) => ({
    id: s.id,
    name: s.name ?? s.title,
    duration_minutes: s.duration_minutes ?? s.durationMinutes,
  })),
  professionals: professionals.data.map((p) => ({
    id: p.id,
    name: p.name ?? p.display_name ?? p.displayName,
  })),
  appointments_next_7d: appointments.data.slice(0, 30),
  api_errors: {
    services: !services.ok,
    professionals: !professionals.ok,
    appointments: !appointments.ok,
  },
};

const defaultProfessional = String(
  $env.QA_DEFAULT_PROFESSIONAL_ID || '00000000-0000-4000-8000-000000004012',
).trim();
const defaultService = String(
  $env.QA_DEFAULT_SERVICE_ID || '00000000-0000-4000-8000-000000004021',
).trim();

return [
  {
    json: {
      inbound,
      enrichment: prep.enrichment ?? {},
      normalized: prep.normalized ?? {},
      core_response: prep.core_response ?? {},
      catalog,
      defaults: {
        professional_id: defaultProfessional,
        service_id: defaultService,
        customer_id: String(
          $env.QA_DEFAULT_CUSTOMER_ID || '00000000-0000-4000-8000-000000004031',
        ).trim(),
      },
    },
  },
];

const j = $input.first().json ?? {};
const UUID_RE =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const okUuid = (v) => typeof v === 'string' && UUID_RE.test(v.trim());
const dateOk = /^\d{4}-\d{2}-\d{2}$/.test(String(j.appointment_date ?? ''));

// Só cria agendamento com intenção explícita + dados completos (evita erro na 1ª mensagem "Boa tarde").
const route =
  j.intent === 'criar_agendamento' &&
  okUuid(j.professional_id) &&
  okUuid(j.service_id) &&
  dateOk
    ? 'criar'
    : 'outbound';

return [{ json: { ...j, _route: route } }];

/** Une rota (intent/UUIDs) com resposta de /availability para os nos seguintes. */
const route = $('Rotear fluxo').first().json ?? {};
const avail = $input.first().json ?? {};
const raw =
  avail.slots ??
  avail.data?.slots ??
  avail.body?.slots ??
  [];
const slots = (Array.isArray(raw) ? raw : [])
  .map((s) => ({
    starts_at: s?.starts_at ?? s?.startsAt ?? null,
    ends_at: s?.ends_at ?? s?.endsAt ?? null,
  }))
  .filter((s) => s.starts_at && s.ends_at);

return [
  {
    json: {
      ...route,
      slots,
      availability: avail,
    },
  },
];

/** Monta POST /appointments — escolhe slot (preferência de horário se informada). */
const row = $input.first().json ?? {};
const slots = Array.isArray(row.slots) ? row.slots : [];

if (!slots.length) {
  return [
    {
      json: {
        ...row,
        appointment_payload: null,
        response_text:
          row.response_text ||
          'No momento nao temos horarios livres para essa data. Quer tentar outro dia?',
      },
    },
  ];
}

function pickSlot(list, preferred) {
  if (!preferred || !/^\d{2}:\d{2}$/.test(preferred)) return list[0];
  const [ph, pm] = preferred.split(':').map((x) => parseInt(x, 10));
  let best = list[0];
  let bestDiff = Number.MAX_SAFE_INTEGER;
  for (const s of list) {
    const d = new Date(s.starts_at);
    const diff = Math.abs(d.getUTCHours() * 60 + d.getUTCMinutes() - (ph * 60 + pm));
    if (diff < bestDiff) {
      bestDiff = diff;
      best = s;
    }
  }
  return best;
}

const slot = pickSlot(slots, row.appointment_time);
const execId = String($execution.id);
const payload = {
  customer_id: row.customer_id,
  professional_id: row.professional_id,
  service_id: row.service_id,
  starts_at: slot.starts_at,
  ends_at: slot.ends_at,
  source: 'whatsapp',
  explicit_confirmation: true,
  idempotency_key: `n8n-wf02-appt-${execId}`,
  notes: 'Agendamento via agente WhatsApp (WF02)',
};

return [{ json: { ...row, ...payload, appointment_payload: payload } }];
